export interface DependabotCreateOrUpdateOrgSecretParams {
  org: string;
  secretName: string;
  visibility: "all" | "private" | "selected" | (string & {});
  encryptedValue?: string;
  keyId?: string;
  selectedRepositoryIds?: (number | string)[];
}

/**
 * Creates or updates an organization secret with an encrypted value. Encrypt your secret using [LibSodium](https://libsodium.gitbook.io/doc/bindings_for_other_languages). For more information, see "[Encrypting secrets for the REST API](https://docs.github.com/rest/guides/encrypting-secrets-for-the-rest-api)." OAuth app tokens and personal access tokens (classic) need the `admin:org` scope to use this endpoint.
 *
 * @param org - The organization name. The name is not case sensitive.
 * @param secretName - The name of the secret.
 * @param visibility - Which type of organization repositories have access to the
 *   organization secret. `selected` means only the repositories specified by
 *   `selected_repository_ids` can access the secret.
 * @param encryptedValue - Value for your secret, encrypted with
 *   [LibSodium](https://libsodium.gitbook.io/doc/bindings_for_other_languages)
 *   using the public key retrieved from the [Get an organization public
 *   key](https://docs.github.com/rest/dependabot/secrets#get-an-organization-publi
 *   c-key) endpoint.
 * @param keyId - ID of the key you used to encrypt the secret.
 * @param selectedRepositoryIds - An array of repository ids that can access the
 *   organization secret. You can only provide a list of repository ids when the
 *   `visibility` is set to `selected`. You can manage the list of selected
 *   repositories using the [List selected repositories for an organization
 *   secret](https://docs.github.com/rest/dependabot/secrets#list-selected-reposito
 *   ries-for-an-organization-secret), [Set selected repositories for an
 *   organization
 *   secret](https://docs.github.com/rest/dependabot/secrets#set-selected-repositor
 *   ies-for-an-organization-secret), and [Remove selected repository from an
 *   organization
 *   secret](https://docs.github.com/rest/dependabot/secrets#remove-selected-reposi
 *   tory-from-an-organization-secret) endpoints.
 */
export async function dependabotCreateOrUpdateOrgSecret(
  config: ClientConfig,
  {
    org,
    secretName,
    visibility,
    encryptedValue,
    keyId,
    selectedRepositoryIds,
  }: DependabotCreateOrUpdateOrgSecretParams,
  requestOptions?: RequestOptions,
): Promise<EmptyObject> {
  if (encryptedValue != null) {
    validatePattern(
      "encrypted_value",
      encryptedValue,
      "^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=|[A-Za-z0-9+/]{4})$",
    );
  }

  const _resp = await sdkRequest<EmptyObject>({
    method: "PUT",
    path: `/orgs/${encodePathSegment(org)}/dependabot/secrets/${encodePathSegment(secretName)}`,
    operationId: "dependabotCreateOrUpdateOrgSecret",
    responseDecoder: "json",
    ...requestOptions,
    body: {
      visibility,
      encrypted_value: encryptedValue,
      key_id: keyId,
      selected_repository_ids: selectedRepositoryIds,
    },
    config,
  });
  return _resp.data;
}

